mode=sys.argv[-1]
q=py('import pathlib,json;O=pathlib.Path('+repr(str(O))+');names='+repr([mode+'-supervisor.json',mode+'-exit.json',mode+'-start.json'])+';r={n:json.loads((O/n).read_text()) for n in names if (O/n).exists()};r["stdoutTail"]=(O/'+repr(mode+'.stdout')+').read_text(errors="replace")[-5000:] if (O/'+repr(mode+'.stdout')+').exists() else None;r["stderrTail"]=(O/'+repr(mode+'.stderr')+').read_text(errors="replace")[-1600:] if (O/'+repr(mode+'.stderr')+').exists() else None;print(json.dumps(r))');save(mode+'-status-'+str(time.time_ns())+'.json',q);print(q['stdout'])
